function injectTouchPrintChrome(doc: Document): void {
  if (doc.getElementById("mazal-touch-print-chrome")) return;

  const pad = "calc(72px + env(safe-area-inset-bottom, 0px))";
  try {
    const prev = doc.body.style.paddingBottom;
    if (!prev) doc.body.style.paddingBottom = pad;
  } catch {
    /* ignore */
  }

  const style = doc.createElement("style");
  style.id = "mazal-touch-print-chrome-styles";
  style.textContent = `
    #mazal-touch-print-chrome {
      position: fixed;
      left: 0;
      right: 0;
      bottom: 0;
      z-index: 2147483647;
      display: flex;
      gap: 10px;
      justify-content: center;
      align-items: center;
      padding: 12px 16px calc(12px + env(safe-area-inset-bottom, 0px));
      background: rgba(30, 30, 30, 0.94);
