      padding: 14px 16px;
      border: none;
      border-radius: 12px;
      font-size: 16px;
      font-weight: 600;
      cursor: pointer;
      touch-action: manipulation;
    }
    #mazal-touch-print-chrome .mazal-print-btn {
      background: #2563eb;
      color: #fff;
    }
    #mazal-touch-print-chrome .mazal-close-btn {
      background: #e5e7eb;
      color: #111827;
    }
    @media print {
      #mazal-touch-print-chrome { display: none !important; }
    }
  `;
  doc.head.appendChild(style);

  const bar = doc.createElement("div");
  bar.id = "mazal-touch-print-chrome";
  bar.setAttribute("dir", "rtl");
  bar.innerHTML =
    '<button type="button" class="mazal-print-btn">הדפס</button><button type="button" class="mazal-close-btn">סגור</button>';

  bar.querySelector(".mazal-print-btn")?.addEventListener("click", () => {
    applyBrandLogoFallback(doc);
    try {
      doc.defaultView?.focus();
      doc.defaultView?.print();
    } catch {
      /* ignore */
    }
  });
  bar.querySelector(".mazal-close-btn")?.addEventListener("click", () => {
    try {
      doc.defaultView?.close();
    } catch {
      /* ignore */
    }
  });
  doc.body.appendChild(bar);
}

