/** דף A4 — בונים כמו במטבח, שתי הזמנות לשורה על גבי A4 */
export function buildA4OrdersHtml(
  orders: Order[],
  portionSizeLabels?: Partial<Record<PortionSize, string>>,
): string {
  const list = sortOrders(orders);
